import{_ as i,o as s,c as a,ah as r}from"./chunks/framework.e_ysbW9u.js";const l="/projects/ROSPug/en/latest/assets/image2.CP7HOWDu.png",o="/projects/ROSPug/en/latest/assets/image11.CqfA8iHm.png",c="/projects/ROSPug/en/latest/assets/image4.D6RlpmIv.png",n="/projects/ROSPug/en/latest/assets/image5.DLZl3aGX.png",g="/projects/ROSPug/en/latest/assets/image6.Yvq0mWc6.png",d="data:image/png;base64,",h="/projects/ROSPug/en/latest/assets/image8.C2_o0HFb.png",p="/projects/ROSPug/en/latest/assets/image10.iB7WD777.png",u="/projects/ROSPug/en/latest/assets/image12.BpnKEhnq.png",m="/projects/ROSPug/en/latest/assets/image13.D0DsDXMR.png",A="/projects/ROSPug/en/latest/assets/image14.BCqEKAU6.png",q="/projects/ROSPug/en/latest/assets/image15.YqwgwnP6.png",w="/projects/ROSPug/en/latest/assets/image16.Dq1uFiCp.png",f="/projects/ROSPug/en/latest/assets/image17.Ckpd3oL5.png",b="/projects/ROSPug/en/latest/assets/image18.Bedm5gyq.png",y="/projects/ROSPug/en/latest/assets/image24.C0dHlP8n.png",v="/projects/ROSPug/en/latest/assets/image3.fI22s6HB.jpeg",x="/projects/ROSPug/en/latest/assets/image25.Cayh1lE6.png",R="/projects/ROSPug/en/latest/assets/image26.-W7HyCXU.png",S="/projects/ROSPug/en/latest/assets/image27.DH39RdbT.png",C="/projects/ROSPug/en/latest/assets/image28.UxIdqEhZ.png",O="/projects/ROSPug/en/latest/assets/image8.DCpz2MDR.png",t="data:image/png;base64,",k="/projects/ROSPug/en/latest/assets/image10.CRoQUvyo.jpeg",z="/projects/ROSPug/en/latest/assets/image11.DIco6IiZ.png",P="/projects/ROSPug/en/latest/assets/image12.RRD7lvZk.png",I="/projects/ROSPug/en/latest/assets/image13.zYp2VBpR.png",j="/projects/ROSPug/en/latest/assets/image14.CQ6XHRLr.png",V="/projects/ROSPug/en/latest/assets/image15.DT_N0A8G.png",E="data:image/png;base64,",B="/projects/ROSPug/en/latest/assets/image17.OhTwwJNY.png",T="/projects/ROSPug/en/latest/assets/image18.B50X8_ka.png",D="/projects/ROSPug/en/latest/assets/image19.ByJsnpYO.png",W="/projects/ROSPug/en/latest/assets/image20.DGdIwkj0.png",J="/projects/ROSPug/en/latest/assets/image21.27ethrGY.png",M="/projects/ROSPug/en/latest/assets/image22.BCWk0eZx.png",U="/projects/ROSPug/en/latest/assets/image23.DpM-j4Ou.png",K="/projects/ROSPug/en/latest/assets/image2.cMMNUvrM.png",F="/projects/ROSPug/en/latest/assets/image3.BislomiP.png",Z=JSON.parse('{"title":"2. Quick User Experience","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2.Quick_User_Exprience.md","filePath":"docs/2.Quick_User_Exprience.md"}'),_={name:"docs/2.Quick_User_Exprience.md"};function Q(N,e,Y,L,H,X){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_2-quick-user-experience" tabindex="-1">2. Quick User Experience <a class="header-anchor" href="#_2-quick-user-experience" aria-label="Permalink to &quot;2. Quick User Experience&quot;">​</a></h1><h2 id="_2-1-app-installation-connection" tabindex="-1">2.1 App Installation &amp; Connection <a class="header-anchor" href="#_2-1-app-installation-connection" aria-label="Permalink to &quot;2.1 App Installation &amp; Connection&quot;">​</a></h2><h3 id="_2-1-1-preparation" tabindex="-1">2.1.1 Preparation <a class="header-anchor" href="#_2-1-1-preparation" aria-label="Permalink to &quot;2.1.1 Preparation&quot;">​</a></h3><ul><li><strong>App Installation</strong></li></ul><p>Scan the QR code below to download.</p><p><strong>Before using the app, ensure that both location service and Wi-Fi are enabled on your phone.</strong></p><img loading="lazy" height="400" width="400" src="'+l+'" class="common_img" style="width:300px;"><ul><li><strong>Start the Robot</strong></li></ul><p>Turn on the switch on the Jetson Nano expansion to start the robot. For detailed guideline, please refer to the tutorial locating in <a href="./1.Getting_ready.html#initial-startup">1.4 Initial Startup</a> .</p><h3 id="_2-1-2-device-connection" tabindex="-1">2.1.2 Device Connection <a class="header-anchor" href="#_2-1-2-device-connection" aria-label="Permalink to &quot;2.1.2 Device Connection&quot;">​</a></h3><p>Once the robot successfully starts up, it will create a WiFi starting with the letter <strong>&quot;HW&quot;</strong>. Connect the app to this WiFi to access and enjoy the games on the app.</p><p>There are two available connection modes, and detailed connection instructions are provided below.</p><ul><li><strong>Introduction to Connection Mode</strong></li></ul><p>Here are the two network modes for the robot dog:</p><p>① AP Direct Connection Mode: The controller can create a hotspot to be connected to by a mobile phone (although it cannot access external networks).</p><p>② STA Local Area Network (LAN) Mode: The controller can actively connect to a specified hotspot/Wi-Fi (allowing access to external networks).</p><p>LAN mode and direct connection mode cannot be active simultaneously. The robot dog defaults to AP Direct Connection mode. Whether users choose AP Direct Connection or STA LAN mode, the game functionality remains consistent.</p><p>It is recommended for users to experience the robot functions under direct connection mode.</p><ul><li><strong>Direct Connection Mode Connection (MUST READ)</strong></li></ul><p>The connection procedure outlined below is based on the Android system but is also applicable to the iOS system.</p><p>Start <strong>&quot;ROSPug&quot;</strong> first.</p><p>① Open <strong>&quot;WonderROS&quot;</strong> app, then select <strong>&quot;ROSPug&quot;</strong>.</p><img loading="lazy" height="900" width="1927" src="'+o+'" class="common_img" style="width:800px;"><p>② Click-on <strong>&quot;+&quot;</strong> at the lower right corner, and choose <strong>&quot;Direct Connection Mode&quot;</strong>.</p><img loading="lazy" height="623" width="1268" src="'+c+'" class="common_img" style="width:800px;"><p>③ Join the WiFi starting with the letter <strong>&quot;HW&quot;</strong>, and the initial password is <strong>&quot;hiwonder&quot;</strong>.</p><img loading="lazy" height="853" width="1735" src="'+n+'" class="common_img" style="width:800px;"><img loading="lazy" height="147" width="412" src="'+g+'" class="common_img"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Please don&#39;t return to the app until the WiFi icon appears on the status bar, otherwise the app will fail to connect to the robot. If the app cannot search any device, please tap-on <img loading="lazy" height="45" width="46" src="'+d+'"> to refresh.</p></section><p>④ After successful network connection, go back to the app. Then the app will connect to the corresponding device automatically. When the <strong>&quot;ROSPug&quot;</strong> icon occurs, it indicates successful match.</p><img loading="lazy" height="614" width="1265" src="'+h+'" class="common_img" style="width:800px;"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>If the box with the message <strong>&quot;Network not available. Whether to continue connecting?&quot;</strong> click on <strong>&quot;Keep Connection.&quot;</strong></p></section><ul><li><strong>LAN Mode Connection Mode (Optional)</strong></li></ul><p>The connection procedure outlined below is based on the Android system but is also applicable to the iOS system</p><p>(1) Connect your phone to random WiFi. Take <strong>&quot;hiwonder_5G&quot;</strong> as example.</p><img loading="lazy" height="155" width="414" src="'+p+'" class="common_img"><p>(2) Open <strong>&quot;WonderROS&quot;</strong> app, then select <strong>&quot;ROSPug&quot;</strong>.</p><img loading="lazy" height="900" width="1927" src="'+o+'" class="common_img" style="width:800px;"><p>(3) Click-on <strong>&quot;+&quot;</strong> at the lower right corner, and choose <strong>&quot;LAN Mode&quot;</strong>. Follow the on-screen instructions to access your phone&#39;s settings and connect to Wi-Fi. After connecting, return to the app.</p><img loading="lazy" height="623" width="1268" src="'+u+'" class="common_img" style="width:800px;"><p>(4) Enter the correct password for the WiFi network your phone is connecting to. Proceed to the next step, ensuring the password is accurate to avoid connection failure.</p><img loading="lazy" height="629" width="1269" src="'+m+'" class="common_img" style="width:800px;"><p>(5) Follow the hint to connect the WiFi starting with the letter <strong>&quot;HW&quot;</strong>.</p><img loading="lazy" height="853" width="1735" src="'+n+'" class="common_img" style="width:800px;"><p>(6) Upon successful network connection, return to the app. The app will then automatically pair with the robot. If a pop-up appears prompting you to join, tap on <strong>&quot;Join.&quot;</strong></p><img loading="lazy" height="626" width="1267" src="'+A+'" class="common_img" style="width:800px;"><p>(7) After a while, the app will search for the <strong>&quot;ROSPug&quot;</strong> device automatically.</p><img loading="lazy" height="625" width="1265" src="'+q+'" class="common_img" style="width:800px;"><p>(8) Get the IP address and ID of the robot dog by pressing <strong>&quot;ROSPug&quot;</strong> icon.</p><img loading="lazy" height="613" width="1265" src="'+w+'" class="common_img" style="width:800px;"><p>(9) If you want to switch to <strong>&quot;Direct Connection Mode&quot;</strong>, you can use screwdriver to press the <strong>&quot;KEY1&quot;</strong> through the hole till it flickers blue.</p><img loading="lazy" height="533" width="864" src="'+f+'" class="common_img"><img loading="lazy" height="775" width="1267" src="'+b+'" class="common_img"><h2 id="_2-2-app-control" tabindex="-1">2.2 App Control <a class="header-anchor" href="#_2-2-app-control" aria-label="Permalink to &quot;2.2 App Control&quot;">​</a></h2><h3 id="_2-2-1-preparation" tabindex="-1">2.2.1 Preparation <a class="header-anchor" href="#_2-2-1-preparation" aria-label="Permalink to &quot;2.2.1 Preparation&quot;">​</a></h3><p>Install the app according to the instructions provided in the folder <a href="./.html">2. Quick User Experience-&gt;2.1 App Installation &amp; Connection</a> .</p><h3 id="_2-2-2-start-the-game" tabindex="-1">2.2.2 Start the Game <a class="header-anchor" href="#_2-2-2-start-the-game" aria-label="Permalink to &quot;2.2.2 Start the Game&quot;">​</a></h3><p>Tap-on <strong>&quot;ROSPug&quot;</strong> robot icon to enter the mode selection interface.</p><img loading="lazy" height="351" width="764" src="'+y+'" class="common_img" style="width:800px;"><ul><li><strong>Robot Control</strong></li></ul><p>(1) Choose <strong>&quot;Robot Control&quot;</strong> to enter the game interface, and the <strong>&quot;ROSPug&quot;</strong> will immediately return to its initial posture.</p><img loading="lazy" height="439" width="901" src="'+v+'" class="common_img" style="width:800px;"><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Icon</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="196" width="445" src="'+x+'"></td><td style="text-align:center;">Control the robot dog to turn and return to the initial position.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="122" width="134" src="'+R+'"></td><td style="text-align:center;">Move the virtual joystick to control the robot to go forward, backward, left and right.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="227" width="377" src="'+S+'"></td><td style="text-align:center;">Display the live camera feed.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="384" width="170" src="'+C+'"></td><td style="text-align:center;">Adjust robot&#39;s height</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="115" width="141" src="'+O+'"></td><td style="text-align:center;">Control the robot to tilt forward, backward, left and right.</td></tr></tbody></table><p>(2) If you need to return to the last interface, tap-on <img loading="lazy" height="48" width="48" src="'+t+'">.</p><ul><li><strong>Robot Performance</strong></li></ul><p>(1) Click-on <strong>&quot;Robot Performance&quot;</strong> icon to enter the game interface.</p><img loading="lazy" height="524" width="1135" src="'+k+'" class="common_img" style="width:800px;"><p>If you wish to customize the action group, please consult the tutorial in the following resource: <a href="./5.Action_Editing_Course.html#app-custom-control">5. Action Editing Course-&gt;5.4 APP Custom Control</a> .</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Icon</strong></th><th style="text-align:center;"><strong>Function Description</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="63" width="130" src="'+z+'"></td><td style="text-align:center;">As an example, when you press the <strong>&quot;Lie Down&quot;</strong> action group button, the robot dog will execute the pre-programmed action.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="69" width="110" src="'+P+'"></td><td style="text-align:center;">Initiate <strong>&quot;self-balancing function&quot;</strong></td></tr></tbody></table><ul><li><strong>Target Tracking</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li>Make sure there are no other objects in the camera&#39;s field of view with the same color as the target, as it may affect the game&#39;s performance.</li><li>Adjust the color pickup range to an appropriate level.</li></ul></section><p>(1) Click-on <strong>&quot;Target Tracking&quot;</strong> icon to enter the game interface.</p><p>This interface is split into two sections:</p><p>① The left side features the controls for toggling functions and selecting colors.</p><p>② The right side shows the camera feed.</p><p><strong>Operation Steps &amp; Program Outcome</strong></p><p>(1) Click the <strong>&quot;Pick&quot;</strong> button, then drag the red circle over the target object in the camera feed to select its color.</p><img loading="lazy" height="442" width="911" src="'+I+'" class="common_img"><p>(2) Then, click-on <strong>&quot;OK&quot;</strong> button, and the selected color will be displayed on the <strong>&quot;Selected Color&quot;</strong> box.</p><img loading="lazy" height="444" width="912" src="'+j+'" class="common_img" style="width:800px;"><p>(3) Click the <strong>&quot;Start&quot;</strong> button to activate the feature. As you move the target object, the robot dog will track and follow it.</p><ul><li><strong>Tag Recognition</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li>Perform the process in well-lit indoor environments.</li><li>Ensure the label remains intact; missing corners or stains may impact the recognition effectiveness.</li></ul></section><p>(1) The interface is divided into two parts:</p><p>① On the left side is the game control area.</p><p>② On the right side is the live camera feed.</p><img loading="lazy" height="434" width="898" src="'+V+'" class="common_img" style="width:800px;"><p>(2) Click the <strong>&quot;Start Recognition&quot;</strong> button and place each tag in front of the camera one at a time. The <strong>&quot;ROSPug&quot;</strong> quadruped robot dog will perform the corresponding action when it recognizes a tag with a specific ID:</p><p>① For <strong>&quot;ID1&quot;</strong>, the robot dog will march in place.</p><p>② For <strong>&quot;ID2&quot;</strong>, the robot dog will do push-ups.</p><p>③ For <strong>&quot;ID3&quot;</strong>, the robot dog will wiggle.</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Icon</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="48" width="114" src="'+E+'"></td><td style="text-align:center;">Start/ close the game</td></tr></tbody></table><p>(3) If you want to return to the mode selection interface, tap-on the blank area to make the navigation bar appear, and tap-on <img loading="lazy" height="48" width="48" src="'+t+'">.</p><ul><li><strong>Face Detection</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Wearing a mask does not affect normal recognition, and the system supports simultaneous recognition of multiple faces within the camera feed.</p></section><p>(1) The interface is divided into two parts:</p><p>① On the left side is the game control area.</p><p>② On the right side is the live camera feed.</p><img loading="lazy" height="433" width="898" src="'+B+'" class="common_img"><p>(2) Press the <strong>&quot;Start&quot;</strong> button, and the robot dog will scan for faces within one-meter radius. Upon recognizing a face, <strong>&quot;ROSPug&quot;</strong> will execute a <strong>&quot;waving&quot;</strong> action.</p><p>(3) If you want to return to the mode selection interface, tap-on the blank area to make the navigation bar appear, and tap-on <img loading="lazy" height="48" width="48" src="'+t+'">.</p><ul><li><strong>Line Following</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li>Before starting, lay out the line-following track with tape and place the robot dog on it.</li><li>Adjust the color picking range to be neither too broad nor too narrow. A range that is too broad may include unintended colors, while a range that is too narrow may miss the target. Also, ensure no objects with colors similar to the target are in the camera feed.</li><li>Once the feature is activated, ensure that no other objects with the target color are within the camera&#39;s view to avoid interfering with the feature&#39;s performance.</li></ul></section><p>(1) The interface is divided into two parts:</p><p>① On the left side is the game control and color picking area.</p><p>② On the right side is the live camera feed.</p><img loading="lazy" height="446" width="915" src="'+T+'" class="common_img"><p><strong>Operation Steps &amp; Program Outcome</strong></p><p>(1) Tap-on <strong>&quot;Pick&quot;</strong> button, then move the red circle on the live camera feed onto the path to capture its color.</p><img loading="lazy" height="445" width="915" src="'+D+'" class="common_img"><img loading="lazy" height="446" width="917" src="'+W+'" class="common_img"><p>(2) Then tap <strong>&quot;OK&quot;</strong> button, and the selected color will be displayed.</p><p>(3) Click-on <strong>&quot;Start&quot;</strong> button to initiate the game, and the robot dog will go forward following the line.</p><img loading="lazy" height="442" width="913" src="'+J+'" class="common_img"><ul><li><strong>Gesture Control</strong></li></ul><p>Click <strong>&quot;Gesture Control&quot;</strong> on the mode selection screen to open the control interface for this feature. The interface is divided into two sections:</p><p>① The left side has the feature controls.</p><p>② The right side shows the camera feed.</p><img loading="lazy" height="444" width="913" src="'+M+'" class="common_img"><ul><li><strong>Lidar</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li>Before starting, place the robot dog on a spacious platform to ensure it has ample room to move.</li><li>In <strong>&quot;Avoid Obstacle&quot;</strong> and <strong>&quot;Lidar Following&quot;</strong> modes, the robot dog detects obstacles within a 90° sector directly in front of it.</li></ul></section><p>(1) Introduction to Game Interface</p><p>Click <strong>&quot;Lidar&quot;</strong> on the mode selection screen to open the control interface for this feature.</p><p>The <strong>&quot;Lidar&quot;</strong> feature includes three modes: <strong>&quot;Avoid Obstacle&quot;</strong>, <strong>&quot;Lidar Following&quot;</strong>, and <strong>&quot;Lidar Guarding&quot;</strong>. The interface is divided into two sections:</p><p>The left side has controls for switching between modes.</p><p>The right side shows the camera feed.</p><img loading="lazy" height="440" width="900" src="'+U+'" class="common_img"><p>(2) Operation Steps &amp; Program Outcome</p><p>① Avoid Obstacle</p><p>The robot dog moves forward continuously. When it detects an obstacle, it automatically changes direction to avoid it.</p><p>② Lidar Following</p><p>The robot dog adjusts its position to keep a consistent distance from detected obstacles.</p><p>③ Lidar Guarding</p><p>The robot dog adjusts its orientation to face any detected obstacles directly.</p><h2 id="_2-3-wireless-handle-control" tabindex="-1">2.3 Wireless Handle Control <a class="header-anchor" href="#_2-3-wireless-handle-control" aria-label="Permalink to &quot;2.3 Wireless Handle Control&quot;">​</a></h2><h3 id="_2-3-1-preparation" tabindex="-1">2.3.1 Preparation <a class="header-anchor" href="#_2-3-1-preparation" aria-label="Permalink to &quot;2.3.1 Preparation&quot;">​</a></h3><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Please ensure that the <strong>&quot;handle receiver&quot;</strong> is inserted before turning on the <strong>&quot;wireless handle&quot;</strong>. If it is already plugged in, disregard this step. Also, when inserting the battery, pay attention to distinguish between the <strong>&quot;positive&quot;</strong> and <strong>&quot;negative terminals&quot;</strong>.</p></section><p>(1) Insert the <strong>&quot;handle receiver&quot;</strong> into any USB interface on <strong>&quot;ROSPug&quot;</strong>. Generally, the <strong>&quot;handle receiver&quot;</strong> has already been inserted to the robot before leaving the factory.</p><p>(2) Please bring your own two <strong>&quot;AAA dry batteries&quot;</strong>. And insert them into the <strong>&quot;battery slot&quot;</strong>.</p><img loading="lazy" height="482" width="1288" src="'+K+'" class="common_img"><h3 id="_2-3-2-device-connection" tabindex="-1">2.3.2 Device Connection <a class="header-anchor" href="#_2-3-2-device-connection" aria-label="Permalink to &quot;2.3.2 Device Connection&quot;">​</a></h3><p>(1) Start <strong>&quot;ROSPug&quot;</strong>. After the robot starts successfully, turn on the <strong>&quot;handle&quot;</strong>. At this time, two <strong>&quot;LED&quot;</strong> lights will flash simultaneously.</p><p>(2) Please wait for a while. Then the robot will pair with the <strong>&quot;handle&quot;</strong> automatically. After successful pairing, the green light will keep lighting up and red <strong>&quot;LED&quot;</strong> light goes out.</p><img loading="lazy" height="309" width="767" src="'+F+'" class="common_img"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>If the <strong>&quot;handle&quot;</strong> doesn&#39;t connect to the <strong>&quot;robot&quot;</strong> within 30s or there is no operation on the <strong>&quot;handle&quot;</strong> within 5 minutes after turning on, it will enter sleep mode. And you can press <strong>&quot;START&quot;</strong> to activate the <strong>&quot;handle&quot;</strong>.</p></section><h3 id="_2-3-3-button-function" tabindex="-1">2.3.3 Button Function <a class="header-anchor" href="#_2-3-3-button-function" aria-label="Permalink to &quot;2.3.3 Button Function&quot;">​</a></h3><p>Below are the functions of the buttons and joysticks, presented from the perspective of <strong>&quot;ROSPug&quot;</strong>.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>A gentle push on the <strong>&quot;joystick&quot;</strong> in any direction can achieve slow-motion movement.</p></section><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Button</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;">START</td><td style="text-align:center;">Restore to Initial Pose</td></tr><tr><td style="text-align:center;">↑</td><td style="text-align:center;">Move Forward</td></tr><tr><td style="text-align:center;">↓</td><td style="text-align:center;">Move Backward</td></tr><tr><td style="text-align:center;">←</td><td style="text-align:center;">Turn Left</td></tr><tr><td style="text-align:center;">→</td><td style="text-align:center;">Turn Right</td></tr><tr><td style="text-align:center;">△</td><td style="text-align:center;">Raise Body Height</td></tr><tr><td style="text-align:center;">×</td><td style="text-align:center;">Lower Body Height</td></tr><tr><td style="text-align:center;">◻</td><td style="text-align:center;">Move Left</td></tr><tr><td style="text-align:center;">○</td><td style="text-align:center;">Move Right</td></tr><tr><td style="text-align:center;">L1</td><td style="text-align:center;">Tilt Body Upward</td></tr><tr><td style="text-align:center;">L2</td><td style="text-align:center;">Tilt Body Downward</td></tr><tr><td style="text-align:center;">R1</td><td style="text-align:center;">Twist Body Left</td></tr><tr><td style="text-align:center;">R2</td><td style="text-align:center;">Twist Body Right</td></tr><tr><td style="text-align:center;">Left joystick</td><td style="text-align:center;">Control the robot to go forward, backward, translate left and right</td></tr><tr><td style="text-align:center;">Right joystick</td><td style="text-align:center;">Turn left and right</td></tr></tbody></table>',149)])])}const $=i(_,[["render",Q]]);export{Z as __pageData,$ as default};
